dec=json.load(open(O/'design_readiness_decision.json'));dec.update({'hierarchical_power_delta_rd_005':float(next(x['power'] for x in pc if x['delta_rd']==.05)),'type1_error_delta0':float(pc[0]['type1_error']),'ci_coverage_95':float(next(x['ci_coverage'] for x in pc if x['delta_rd']==.05)),'loso_min_power':float(ll.power.min()),'max_episode_information_share':float(conc.loc[conc.level=='episode','information_share'].iloc[0]),'max_oblast_information_share':float(conc.loc[conc.level=='oblast','information_share'].iloc[0]),'max_asn_information_share':float(conc.loc[conc.level=='role_stratum','information_share'].iloc[0]),'recommended_estimator':'paired absolute-risk DID with /24 design-effect variance (synthetic-readiness only)','largest_limitation':'Four treated episodes lack deterministic controls; hierarchical metrics use control-window nuisance and synthetic outcomes, not observed treated effects.','sap_freeze_ready':False});open(O/'design_readiness_decision.json','w').write(json.dumps(dec,indent=2))
p=O/'NEGATIVE_CONTROL_DESIGN_REPORT.md';s=p.read_text();s+='\\n## Hierarchical outcome-blind simulation\\n\\nControl-window nuisance was used only to parameterize synthetic outcomes. No treated loss outcome or formal role effect was computed. The paired absolute-risk DID simulation used 2,000 draws per SESOI and ICC scenario with /24 design-effect variance. Delta_RD=0.05 power='+str(round(dec['hierarchical_power_delta_rd_005'],3))+', Delta_RD=0 Type-I error='+str(round(dec['type1_error_delta0'],3))+', 95% CI coverage='+str(round(dec['ci_coverage_95'],3))+', minimum leave-one-pair-out power='+str(round(dec['loso_min_power'],3))+'. These are synthetic design-readiness quantities, not observed effects.\\n';p.write_text(s)
